using System;
namespace BeamScheduleFormatter {
static class ReportWatermarkAssets {
 internal const int DtceWidth=600,DtceHeight=600;
 internal const string Dtce="";
 internal const int DpwhWidth=480,DpwhHeight=480;
 internal const string Dpwh="";
 internal static byte[] Jpeg{get{return Convert.FromBase64String(
#if ADMIN_APP
 Dtce
#else
 Dpwh
#endif
 );}}
 internal static int Width{get{return
#if ADMIN_APP
 DtceWidth;
#else
 DpwhWidth;
#endif
 }}
 internal static int Height{get{return
#if ADMIN_APP
 DtceHeight;
#else
 DpwhHeight;
#endif
 }}
}
}
